Method.Implementation:
#;We need to trap all errors so we can close the LDAP channel, otherwise a memory #;leak can occur. s $zt="Error"
#;No error initially s Status=0
s AdminDN= ..%CredentialsObj.Username // "uid=admin,ou=system" s AdminPW= ..%CredentialsObj.Password //"secret" ;s BaseDN= "ou=consumers,o=ihc" //"ou=people,dc=example,dc=com"
//s LD=##Class(%SYS.LDAP).Init("127.0.0.1",10389) s LD=##Class(%SYS.LDAP).Init(..LDAPServer,..LDAPPort)
$$$TRACE("LD"_LD)
$$$TRACE("..%CredentialsObj.Username "_..%CredentialsObj.Username ) $$$TRACE("..%CredentialsObj.Password "_..%CredentialsObj.Password )
#;Ok, now we bind (authenticate) to the server using the DN of the LDAP administrator who has #;read access to the entire LDAP database. We need to do this first so we have #;privileges to search for the user we want to authenticate. s Status=##Class(%SYS.LDAP).SimpleBinds(LD,AdminDN,AdminPW) i Status'=$zhex(00) { s Status=Status_",ldap_Simple_Bind(AdminDN) - "_##Class(%SYS.LDAP).Err2String(Status) $$$TRACE("SimpleBinds Status inside error if :"_Status) q } $$$TRACE("SimpleBinds status : "_Status) #;Now that we have read access to the LDAP server, we need to search the LDAP #;database for the user we want to authenticate in order to get their DN.
s Filter= pFilter //"telephoneNumber=123456789"
s AttributeList=$LB("cn")
#;$$$LDAPSCOPESUBTREE means to search the entire tree beneath the BaseDN used. s SearchScope= $zhex(02)
#;Max length of time the search can last. s Timeout=10
#;Return just the first thing we find. s SizeLimit=1 s Status=##Class(%SYS.LDAP).SearchExts(LD,BaseDN,SearchScope,Filter,AttributeList,0,"","",Timeout,SizeLimit,.SearchResult) i Status'=$zhex(00) { $$$TRACE("SearchExts Status:"_Status) q Status }
#;See how many entries were returned by the search. s NumEntries=##Class(%SYS.LDAP).CountEntries(LD,SearchResult) i NumEntries=-1 { s Status=##Class(%SYS.LDAP).GetError(LD) s Status=Status_",ldap_Count_Entries - "_##Class(%SYS.LDAP).Err2String(Status) $$$TRACE(Status) q Status }
#;If NumEntries=0, then either there is no LDAP user for the username #;in the database, or the BaseDN parameter needs to be set higher in the tree. i NumEntries=0 { s Status="NumEntries=0 , 1,User "_pFilter_" does not exist" $$$TRACE(Status) q Status }
#;If the search returned too many items, then the Filter is probably wrong. i NumEntries>1 { s Status="NumEntries>1 1,LDAP Filter is not unique" $$$TRACE(Status) q Status }
#;Now get the pointer to the first (and only) entry in the returned search list. s CurrentEntry=##Class(%SYS.LDAP).FirstEntry(LD,SearchResult) i CurrentEntry=0 { s Status=##Class(%SYS.LDAP).GetError(LD) s Status=Status_",ldap_FirstEntry from SearchResult - "_##Class(%SYS.LDAP).Err2String(Status) $$$TRACE(Status) q Status }
#;Retrieve all the user's attributes we asked for. Note that we are still in the context of the #;Admin user who has privileges to search the LDAP database.
s Attribute=##Class(%SYS.LDAP).FirstAttribute(LD,CurrentEntry,.Ptr) while (Attribute'="") { s Values=##Class(%SYS.LDAP).GetValues(LD,CurrentEntry,Attribute) w "Attribute: "_Attribute," Values:",$LISTTOSTRING(Values),! s Attribute=##Class(%SYS.LDAP).NextAttribute(LD,CurrentEntry,.Ptr) }
s UserDN=##Class(%SYS.LDAP).GetDN(LD,CurrentEntry) ;w "UserDN:",UserDN,! $$$TRACE("UserDN : "_UserDN)
/*// Note that "2" indicates replace. See the class doc for ModifyExts for explanation of: 0,1,2 s Attr1=$lb(2,AttrName,$lb(AttrVal)) s Attributes=$lb(Attr1)*/
If pAction=1 { s Attr1=$lb(0,AttrName,$lb(AttrVal)) s Attributes=$lb(Attr1) s Status=##Class(%SYS.LDAP).ModifyExts(LD,UserDN,Attributes,"","") $$$TRACE(pAction_"ModifyExts status "_Status) } ElseIf pAction=2 { s Attr1=$lb(2,AttrName,$lb(AttrVal)) s Attributes=$lb(Attr1) s Status=##Class(%SYS.LDAP).ModifyExts(LD,UserDN,Attributes,"","") $$$TRACE(pAction_"ModifyExts status "_Status) }
i Status'=$zhex(00) { $$$TRACE("ModifyExts error: "_Status_" - "_##Class(%SYS.LDAP).Err2String(Status)) q Status }
// Important: we need to clean up to avoid memory leaks. We should do this after errors/failures also. // This is only sample code: there might be other things that need to be cleaned up i $d(SearchResult) d ##Class(%SYS.LDAP).MsgFree(SearchResult) i $d(Page) d ##Class(%SYS.LDAP).SearchAbandonPage(LD,Page) i $d(LD) s Status=##Class(%SYS.LDAP).UnBinds(LD) $$$TRACE("UnBinds Status"_Status) I Status=$$$LDAPSUCCESS { Quit $$$OK } Else { Quit ##Class(%SYS.LDAP).Err2String(Status) }
q
Error s $zt="" s Status="1,Cache error: "_$ze q Status

#;We need to trap all errors so we can close the LDAP channel, otherwise a memory #;leak can occur. s $zt="Error"
#;No error initially s Status=0 Set RetVal = 0
s AdminDN= ..%CredentialsObj.Username // "uid=admin,ou=system" s AdminPW= ..%CredentialsObj.Password //"secret" s BaseDN= SearchDN // "ou=consumers,o=ihc" //"ou=people,dc=example,dc=com"
//s LD=##Class(%SYS.LDAP).Init("127.0.0.1",10389) s LD=##Class(%SYS.LDAP).Init(..LDAPServer,..LDAPPort)
$$$TRACE("LD"_LD)
$$$TRACE("..%CredentialsObj.Username "_..%CredentialsObj.Username ) $$$TRACE("..%CredentialsObj.Password "_..%CredentialsObj.Password )
#;Ok, now we bind (authenticate) to the server using the DN of the LDAP administrator who has #;read access to the entire LDAP database. We need to do this first so we have #;privileges to search for the user we want to authenticate. s Status=##Class(%SYS.LDAP).SimpleBinds(LD,AdminDN,AdminPW) i Status'=$zhex(00) { s Status=Status_",ldap_Simple_Bind(AdminDN) - "_##Class(%SYS.LDAP).Err2String(Status) $$$TRACE("SimpleBinds Status inside error if :"_Status) q } $$$TRACE("SimpleBinds status : "_Status) #;Now that we have read access to the LDAP server, we need to search the LDAP #;database for the user we want to authenticate in order to get their DN.
s Filter= pFilter //"telephoneNumber=123456789"
s AttributeList=$LB("cn")
#;$$$LDAPSCOPESUBTREE means to search the entire tree beneath the BaseDN used. s SearchScope= $zhex(02)
#;Max length of time the search can last. s Timeout=10
#;Return just the first thing we find. s SizeLimit=1 s Status=##Class(%SYS.LDAP).SearchExts(LD,BaseDN,SearchScope,Filter,AttributeList,0,"","",Timeout,SizeLimit,.SearchResult) $$$TRACE("SearchExts Status:"_Status) i Status'=$zhex(00) { $$$TRACE("SearchExts Status:"_Status) q Status }
#;See how many entries were returned by the search. s NumEntries=##Class(%SYS.LDAP).CountEntries(LD,SearchResult) $$$TRACE("NumEntries"_NumEntries) i NumEntries=-1 { s Status=##Class(%SYS.LDAP).GetError(LD) s Status=Status_",ldap_Count_Entries - "_##Class(%SYS.LDAP).Err2String(Status) $$$TRACE(Status) q Status }
#;If NumEntries=0, then either there is no LDAP user for the username #;in the database, or the BaseDN parameter needs to be set higher in the tree. i NumEntries>=1 { s Status="Found entries for the SearchDN and filter " $$$TRACE(Status) Set RetVal = NumEntries q $$$OK }
i NumEntries=0 { s Status="Found no entries for the SearchDN and filter " $$$TRACE(Status) Set RetVal = NumEntries Quit $$$OK }
// Important: we need to clean up to avoid memory leaks. We should do this after errors/failures also. // This is only sample code: there might be other things that need to be cleaned up i $d(SearchResult) d ##Class(%SYS.LDAP).MsgFree(SearchResult) i $d(Page) d ##Class(%SYS.LDAP).SearchAbandonPage(LD,Page) i $d(LD) s Status=##Class(%SYS.LDAP).UnBinds(LD) $$$TRACE("UnBinds Status"_Status) I Status=$$$LDAPSUCCESS { Quit $$$OK } Else { Quit ##Class(%SYS.LDAP).Err2String(Status) }
q
Error s $zt="" s Status="1,Cache error: "_$ze i $d(SearchResult) d ##Class(%SYS.LDAP).MsgFree(SearchResult) i $d(Page) d ##Class(%SYS.LDAP).SearchAbandonPage(LD,Page) i $d(LD) s Status=##Class(%SYS.LDAP).UnBinds(LD) q Status
